// Client-side filter for the rule catalog (docs/rule-catalog.md, generated by RuleCatalogDocGenerator).
// The form ships hidden so the page still works as a plain list without JavaScript.
(function () {
  var form = document.querySelector('.catalog-filter');
  if (!form) return;

  var input = form.querySelector('#rule-filter');
  var toggles = form.querySelectorAll('input[data-filter]');
  var status = form.querySelector('.catalog-filter__status');
  var cards = Array.prototype.slice.call(document.querySelectorAll('.rule-card'));
  var domains = Array.prototype.slice.call(document.querySelectorAll('.rule-domain'));
  var searchText = cards.map(function (card) {
    return card.textContent.replace(/\s+/g, ' ').toLowerCase();
  });

  function apply() {
    var terms = input.value.toLowerCase().split(/\s+/).filter(Boolean);
    var fixOnly = form.querySelector('input[data-filter="fix"]').checked;
    var warningsOnly = form.querySelector('input[data-filter="warning"]').checked;
    var shown = 0;

    cards.forEach(function (card, index) {
      var visible = terms.every(function (term) { return searchText[index].indexOf(term) !== -1; }) &&
        (!fixOnly || card.getAttribute('data-fix') === 'true') &&
        (!warningsOnly || card.getAttribute('data-severity') === 'warning');
      card.hidden = !visible;
      if (visible) shown++;
    });

    domains.forEach(function (domain) {
      domain.hidden = !domain.querySelector('.rule-card:not([hidden])');
    });

    status.textContent = shown === cards.length
      ? cards.length + ' rules'
      : shown + ' of ' + cards.length + ' rules match';

    try {
      var url = new URL(window.location.href);
      if (input.value) url.searchParams.set('q', input.value); else url.searchParams.delete('q');
      window.history.replaceState(null, '', url);
    } catch (e) { /* history is optional */ }
  }

  try {
    var initial = new URL(window.location.href).searchParams.get('q');
    if (initial) input.value = initial;
  } catch (e) { /* ignore */ }

  form.addEventListener('submit', function (event) { event.preventDefault(); });
  input.addEventListener('input', apply);
  Array.prototype.forEach.call(toggles, function (toggle) { toggle.addEventListener('change', apply); });
  form.hidden = false;
  apply();
})();
